def test_rate_limit_separate_for_register_and_login(self, client_with_rate_limiting):
    """Register and login share the same rate limit."""
    # Make 50 register requests
    for i in range(50):
        client_with_rate_limiting.post(
            "/auth/register",
            json={"username": f"user{i}", "password": "pass"}
        )

    # Make 50 login requests
    client_with_rate_limiting.post(
        "/auth/register",
        json={"username": "shared_user", "password": "pass"}
    )
    for i in range(50):
        client_with_rate_limiting.post(
            "/auth/login",
            json={"username": "shared_user", "password": "pass"}
        )

    # The 101st request (combined) should be rate limited
    response = client_with_rate_limiting.post(
        "/auth/login",
        json={"username": "shared_user", "password": "pass"}
    )
    assert response.status_code == 429

